function basicAttack(force=false){let hero=HEROES[state.active],range=['mage','heal','ranged','support'].includes(hero.style)?255:98;let enemy=runtime.enemy.find(e=>e.id===runtime.target && e.hp>0)||nearestEnemy(range);if(!enemy){if(force)toast('Get closer to an enemy to attack.');return false}if(Math.hypot(enemy.x-runtime.x,enemy.y-runtime.y)>range){if(force)toast('Target is out of range.');return false;}if(runtime.time<runtime.attackUntil)return false;attackPulse[hero.id]=runtime.time;hitEnemy(enemy,hero.id);runtime.attackUntil=runtime.time+Math.max(470,1020/(1+combinedStats(hero.id).speed/100));return true}
