function renderCodex(){let rows=TIERS.map(t=>`<tr><td style="color:${t.color}"><b>${t.name}</b></td><td>+${t.at}/15</td><td>${t.slots} substats</td></tr>`).join('');$('codexContent').innerHTML=`<div class="codexCols"><div class="panel"><h2>Equipment ascension</h2><table class="codexTable"><thead><tr><th>Rarity</th><th>Stage</th><th>Rolls</th></tr></thead><tbody>${rows}</tbody></table><p class="micro">Prototype fills the +9 midpoint with Mythic. All six milestones can be renamed in data.js as the rules are finalized. Item specials begin at +3.</p></div><div class="panel"><h2>Combat targets</h2><table class="codexTable"><tr><td>Regular late-game hero</td><td>~30,000 HP</td></tr><tr><td>Tank late-game build</td><td>50K–70K+ HP</td></tr><tr><td>Equipment HP bonus</td><td>Up to +28%</td></tr><tr><td>Standard dungeon boss</td><td>150K–500K HP</td></tr><tr><td>Elite boss</td><td>1M–5M HP</td></tr><tr><td>World boss (future)</td><td>5M–20M+ HP</td></tr></table><p class="micro">The Ashen Titan in the starter vault has 250K HP. Its fight is a prototype, not final balance.</p></div><div class="panel"><h2>Guild progression</h2><ul class="list"><li>20 original playable hero designs, expandable roster.</li><li>Twenty in-world sprites derived from the original illustrated hero cards; basic idle and movement motion.</li><li>3 active party members initially; earn fourth and fifth slots.</li><li>One directly controlled hero, remaining companions fight with simple AI.</li><li>Random equipment rolls only; fixed character base stats.</li><li>Class-specific relics have independent +10 upgrades.</li><li>Weapon, armor and accessory enhancements stop at +15.</li><li>Visual rarity and Masterwork effects.</li></ul></div><div class="panel"><h2>Multiplayer roadmap</h2><ul class="list"><li>Account level 11 unlocks online access when servers exist.</li><li>Story mode remains optional and independent.</li><li>First: co-op exploration, then opt-in duels and the Arena.</li><li>Later: dedicated PvP worlds, guild activities and raids.</li><li>Ranked matches will need server-verified, normalized combat.</li></ul><p class="micro">The online features listed here are design plans, not implemented multiplayer.</p></div><div class="panel"><h2>Controls</h2><p>Move with WASD, arrow keys, touch directional pad or click/tap ground. Basic attacks trigger automatically near enemies; use Strike to force a hit. Special move: SPACE or the SKILL button. Tap party portraits to switch the controlled hero. Click enemies to select them.</p></div></div>`}
function renderOnline(){$('multiplayerContent').innerHTML=`<span class="eyebrow">ACCOUNT LEVEL ${state.accountLevel}</span><h2>${state.accountLevel>=11?'Eligible for future multiplayer':'Arena & Duels · Unlock at level 11'}</h2><div class="meter big"><div style="width:${clamp(state.accountLevel/11*100,0,100)}%;background:linear-gradient(90deg,#4ba3d8,#dfb86a)"></div></div><p>${state.accountLevel<11?`Reach account level 11. Current level ${state.accountLevel}, next level requires ${fmt(xpNeed(state.accountLevel)-state.accountXp)} more XP.`:'Account-level requirement met.'} This build works offline and does not host public multiplayer sessions.</p><div class="dashboard"><div class="panel"><h2>🏟 Ranked Arena</h2><p>Planned: fair skill-based matches with normalized equipment.</p><button disabled>Requires online server</button></div><div class="panel"><h2>⚔ Opt-in Duels</h2><p>Planned: both players must accept before combat begins.</p><button disabled>Requires online server</button></div><div class="panel"><h2>🏰 Co-op Adventures</h2><p>Planned: explore and challenge bosses with friends.</p><button disabled>Requires online server</button></div><div class="panel"><h2>🌍 PvP Worlds</h2><p>Future phase: dedicated opt-in PvP worlds, separate from normal story mode.</p><button disabled>Future expansion</button></div></div>`}
function renderSettings(){Settings.render($('settingsContent'),{toastFn:toast,switchTab,resetAdventure:null})}
function renderAll(){renderCounters();renderAdventure();renderHeroes();renderEquipment();renderForge();renderGuild();renderCodex();renderOnline()}
function switchTab(tab){if(!$(tab))return;if(Settings.isEditing()&&tab!=='adventure')Settings.stopEdit();view.tab=tab;Hud.onTab(tab);document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id===tab));document.querySelectorAll('.bottomNav button').forEach(b=>b.classList.toggle('active',b.dataset.go===tab));if(tab==='adventure')renderAdventure();if(tab==='heroes')renderHeroes();if(tab==='equipment')renderEquipment();if(tab==='forge')renderForge();if(tab==='guild')renderGuild();if(tab==='multiplayer')renderOnline();if(tab==='settings')renderSettings();window.scrollTo({top:0,behavior:'instant'})}
function pay(g,s=0){if(state.gold<g||state.shards<s){toast('Not enough gold or shards. Explore to earn more.');return false}state.gold-=g;state.shards-=s;return true}
const modal=(html)=>{$('modalContents').innerHTML=html;$('modal').showModal()};$('closeModal').onclick=()=>$('modal').close();$('questBtn').onclick=()=>{let q=[['The First Hunt','Defeat three creatures in Whispering Wilds.','Reward: 225 gold'],['Ashen Secrets','Defeat three Ashen Ruins enemies.','Reward: 35 shards'],['The Titan Trial','Defeat the Ashen Titan (250,000 HP).','Reward: 2,000 gold'],['Guild of Legends','Congratulations! Continue finding loot and recruiting heroes.','More story chapters are planned.']][state.questStep];modal(`<span class="eyebrow">QUEST JOURNAL</span><h2>${q[0]}</h2><p>${q[1]}</p><p>${q[2]}</p>`)};
$('bossDifficulty').addEventListener('change',e=>{state.bossDifficulty=e.target.value;if(state.zone==='boss')enterZone('boss');else save();toast(`Titan Vault difficulty: ${e.target.selectedOptions[0].text}`)});
const event=async e=>{let b=e.target.closest('[data-go],[data-zone],[data-hero],[data-switch],[data-add],[data-remove],[data-recruit],[data-item],[data-forgeselect],[data-forgeitem],[data-filter],[data-enhance],[data-boost],[data-reroll],[data-ability],[data-equip],[data-relic],[data-upgradeparty],[data-upgradeforge],[data-backup],[data-import],[data-reset]');if(!b)return;let d=b.dataset;if(d.go){switchTab(d.go);return}if(d.zone){if((d.zone==='boss'||d.zone==='frost')&&state.accountLevel<(d.zone==='boss'?5:3))toast('Warning: this boss is intended for higher-level adventurers.');enterZone(d.zone);return}if(d.hero!==undefined){view.hero=+d.hero;renderHeroes();return}if(d.switch!==undefined){let nid=+d.switch;if(!state.party.includes(nid))return;if(nid!==state.active){let c=runtime.companions[nid],ox=runtime.x,oy=runtime.y;delete runtime.companions[nid];if(c){runtime.x=c.x;runtime.y=c.y}runtime.companions[state.active]={x:ox,y:oy,attackAt:0};runtime.walkingTarget=null}state.active=nid;runtime.attackUntil=0;runtime.abilityUntil=0;renderAdventure();save();return}if(d.item){view.item=d.item;renderEquipment();return}if(d.forgeselect){view.forge=d.forgeselect;renderForge();return}if(d.forgeitem){view.forge=d.forgeitem;switchTab('forge');return}if(d.filter){view.filter=d.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter===d.filter));renderEquipment();return}if(d.recruit!==undefined){let id=+d.recruit,fee=350+state.unlocked.length*145;if(state.unlocked.includes(id)||!pay(fee))return;state.unlocked.push(id);state.heroLevels[id]=1;state.loadouts[id]={};state.relicLevels[id]=0;let newItem=baseItem('weapon',id);state.gear.push(newItem);state.loadouts[id].weapon=newItem.id;log(`Recruited ${HEROES[id].name}!`)}
 else if(d.add!==undefined){let id=+d.add;if(state.party.includes(id)||state.party.length>=state.partyCap)return;state.party.push(id);runtime.hp[id]=heroMax(id);log(`${HEROES[id].name} joined the traveling party.`)}
 else if(d.remove!==undefined){let id=+d.remove;if(state.party.length<=1)return;state.party=state.party.filter(n=>n!==id);delete runtime.companions[id];if(state.active===id)state.active=state.party[0];log(`${HEROES[id].name} returned to the guild.`)}
 else if(d.equip){let it=state.gear.find(i=>i.id===d.equip);if(!it)return;state.loadouts[it.heroId]??={};state.loadouts[it.heroId][it.type]=it.id;runtime.hp[it.heroId]=Math.min(runtime.hp[it.heroId]??heroMax(it.heroId),heroMax(it.heroId));toast(`${it.name} equipped on ${HEROES[it.heroId].name}.`)}
 else if(d.enhance){let it=state.gear.find(i=>i.id===d.enhance);if(!it||it.level>=15)return;let old=tier(it).name,g=100+it.level*120,s=2+Math.floor(it.level*1.5);if(!pay(g,s))return;advanceItem(it);let now=tier(it).name;toast(old===now?`${it.name} enhanced to +${it.level}!`:`RARITY ASCENDED: ${old} → ${now}!`);if(it.level===15)log(`MASTERWORK! ${it.name} reached +15/15.`)}
 else if(d.boost!==undefined){let it=getSelectedItem(true),stat=it.substats[+d.boost];if(!stat)return;let p=SUBSTAT_POOL.find(s=>s.id===stat.id),v=stat.value+stat.boost*p.step;if(stat.boost>=10||v>=p.cap)return;let g=Math.ceil(75+(stat.boost+1)*85),s=2+stat.boost;if(!pay(g,s))return;stat.boost++;toast(`${p.name} improved to +${stat.boost}/10.`)}
 else if(d.reroll!==undefined){let it=getSelectedItem(true),i=+d.reroll;if(!it.substats[i]||!pay(130,3))return;let exclude=it.substats.filter((_,k)=>k!==i).map(p=>p.id);it.substats[i]=makeRoll(exclude);toast('Substat rerolled. New value applied.');}
 else if(d.ability){let it=state.gear.find(i=>i.id===d.ability);if(!it?.ability||!pay(280,6))return;let list=ABILITIES.filter(a=>a.id!==it.ability);it.ability=sample(list).id;toast(`New ability: ${abilityName(it).name}`)}
 else if(d.relic!==undefined){let id=+d.relic,lv=state.relicLevels[id]||0;if(lv>=10||!pay(110*(lv+1),2+lv))return;state.relicLevels[id]=lv+1;toast(`${HEROES[id].relic} upgraded to ${lv+1}/10!`)}
 else if(d.upgradeparty!==undefined){let fee=700+(state.partyCap-3)*1050;if(state.partyCap>=5||!pay(fee,15))return;state.partyCap++;state.guildLevel++;toast(`Party capacity is now ${state.partyCap}!`)}
 else if(d.upgradeforge!==undefined){let fee=500+state.forgeLevel*650;if(state.forgeLevel>=5||!pay(fee,12))return;state.forgeLevel++;state.guildLevel++;toast(`Forge upgraded to level ${state.forgeLevel}!`)}
 else if(d.backup!==undefined){let data=JSON.stringify(state,null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`varnethryl-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup exported. Keep the file safe.');return}
 else if(d.import!==undefined){$('importFile').click();return}
 else if(d.reset!==undefined){modal(`<h2>Reset the adventure?</h2><p>This deletes your locally saved progress. Export a JSON backup first if you want to keep it.</p><button class="danger" id="confirmReset">Delete all local progress</button>`);$('confirmReset').onclick=()=>{localStorage.removeItem(key);state=freshState();Settings.adopt(state,()=>save());runtime.hp={};resetHP();enterZone('village');$('modal').close();renderAll();toast('Local progress reset.');};return}
 renderAll();save();};document.addEventListener('click',event);
$('importFile').addEventListener('change',async e=>{let file=e.target.files[0];if(!file)return;try{let s=JSON.parse(await file.text());if(s.version!==1||!Array.isArray(s.unlocked)||!Array.isArray(s.party)||!Array.isArray(s.gear)||!s.loadouts)throw new Error('Incompatible save');modal(`<h2>Restore backup?</h2><p>This will replace your existing saved guild. You may wish to export your current save first.</p><button class="gold" id="confirmImport">Restore this backup</button>`);$('confirmImport').onclick=()=>{state={...freshState(),...s};Settings.adopt(state,()=>save());runtime.hp={};resetHP();enterZone(state.zone);renderAll();$('modal').close();toast('Backup restored.');save();}}catch(err){toast(`Import failed: ${err.message}`)}e.target.value=''});
const fast=(el,fn)=>{el.addEventListener('pointerdown',e=>{e.preventDefault();fn();renderTarget();Settings.haptic(8)})};fast($('attackBtn'),()=>{Settings.sfx('hit');basicAttack(true)});fast($('skillBtn'),()=>{Settings.sfx('skill');specialAttack()});
let motionKeys=new Set(['w','a','s','d','ArrowUp','ArrowLeft','ArrowDown','ArrowRight']);window.addEventListener('keydown',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;if(motionKeys.has(k)){if(e.target.tagName!=='INPUT'){e.preventDefault();runtime.keys.add(k)}}if(k===' '&&view.tab==='adventure'){e.preventDefault();specialAttack()}if(k==='Escape'&&$('modal').open)$('modal').close()});window.addEventListener('keyup',e=>runtime.keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>runtime.keys.clear());document.querySelectorAll('[data-dir]').forEach(b=>{let key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();runtime.keys.add(key);b.setPointerCapture(e.pointerId)});b.addEventListener('pointerup',()=>runtime.keys.delete(key));b.addEventListener('pointercancel',()=>runtime.keys.delete(key));b.addEventListener('lostpointercapture',()=>runtime.keys.delete(key))});
const canvas=$('game');canvas.addEventListener('pointerdown',e=>{let r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)+runtime.camera.x,y=(e.clientY-r.top)+runtime.camera.y;let target=nearestEnemy(38,x,y);if(target){runtime.target=target.id;toast(`Target: ${target.name}`)}else runtime.walkingTarget={x,y};});
if(matchMedia('(pointer:coarse)').matches)document.querySelectorAll('.hudLine')[1].innerHTML='<span>Tap an enemy to target</span><span>Drag/tap ground to move</span>';
let lastFrame=performance.now(),lastHud=0;function frame(now){let dt=Math.min(55,now-lastFrame);lastFrame=now;if(!document.hidden&&view.tab==='adventure')tick(dt);if(view.tab==='adventure'){drawWorld();Controls.refresh();if(now-lastHud>400){lastHud=now;renderParty();renderTarget();$('enemyCount').textContent=state.zone==='village'?'Safe territory':`${runtime.enemy.length} enemies`;}}requestAnimationFrame(frame)}
resetHP();renderAll();if(state.zone==='boss')spawnEnemies();requestAnimationFrame(frame);document.addEventListener('visibilitychange',()=>{if(document.hidden){save();runtime.keys.clear()}});
